create table if not exists iam.stores (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references iam.tenants(id) on delete cascade,
  code text not null,
  display_name text not null,
  status text not null check (status in ('active', 'inactive')),
  created_at timestamptz not null default now(),
  unique (tenant_id, code),
  unique (tenant_id, id)
);

do $$
begin
  -- Guard for environments where iam.memberships was created without a
  -- composite PK/UNIQUE on (tenant_id, user_id). The FK below requires it.
  if exists (
    select 1
    from iam.memberships m
    group by m.tenant_id, m.user_id
    having count(*) > 1
  ) then
    raise exception using errcode = 'P0001',
      message = 'Duplicate rows detected in iam.memberships(tenant_id, user_id). Resolve duplicates before applying active-store context migration.';
  end if;

  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'iam'
      and t.relname = 'memberships'
      and c.contype in ('p', 'u')
      and c.conkey = array[
        (select attnum from pg_attribute where attrelid = t.oid and attname = 'tenant_id'),
        (select attnum from pg_attribute where attrelid = t.oid and attname = 'user_id')
      ]::smallint[]
  ) then
    alter table iam.memberships
      add constraint memberships_tenant_user_unique unique (tenant_id, user_id);
  end if;
end;
$$;

create table if not exists iam.membership_store_scopes (
  tenant_id uuid not null references iam.tenants(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  store_id uuid not null,
  is_default boolean not null default false,
  primary key (tenant_id, user_id, store_id),
  foreign key (tenant_id, user_id)
    references iam.memberships(tenant_id, user_id) on delete cascade,
  foreign key (tenant_id, store_id)
    references iam.stores(tenant_id, id) on delete cascade
);

create unique index if not exists membership_store_scopes_one_default
  on iam.membership_store_scopes (tenant_id, user_id)
  where is_default;

alter table iam.stores enable row level security;
alter table iam.membership_store_scopes enable row level security;

drop policy if exists stores_member_read on iam.stores;
create policy stores_member_read on iam.stores
  for select
  to authenticated
  using (
    exists (
      select 1
      from iam.memberships m
      where m.tenant_id = stores.tenant_id
        and m.user_id = auth.uid()
    )
  );

drop policy if exists membership_store_scopes_self_read on iam.membership_store_scopes;
create policy membership_store_scopes_self_read on iam.membership_store_scopes
  for select
  to authenticated
  using (
    user_id = auth.uid()
    and exists (
      select 1
      from iam.memberships m
      where m.tenant_id = membership_store_scopes.tenant_id
        and m.user_id = auth.uid()
    )
  );

create or replace function iam.get_session_context(p_tenant_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_ids uuid[];
  v_tenant_id uuid;
  v_role text;
  v_store_ids uuid[];
  v_active_store_id uuid;
  v_active_store_code text;
  v_active_store_display_name text;
  v_permissions text[];
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"NOT_AUTHENTICATED","message":"Not authenticated.","details":{}}';
  end if;

  if p_tenant_id is not null then
    select array_agg(m.tenant_id)
    into v_tenant_ids
    from iam.memberships m
    where m.user_id = v_user_id
      and m.tenant_id = p_tenant_id;
  else
    select array_agg(m.tenant_id)
    into v_tenant_ids
    from iam.memberships m
    where m.user_id = v_user_id;
  end if;

  if coalesce(cardinality(v_tenant_ids), 0) = 0 then
    return null;
  end if;

  if cardinality(v_tenant_ids) <> 1 then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Exactly one tenant context is required.","details":{}}';
  end if;

  v_tenant_id := v_tenant_ids[1];

  select m.role
  into v_role
  from iam.memberships m
  where m.tenant_id = v_tenant_id
    and m.user_id = v_user_id;

  select array_agg(scope.store_id)
  into v_store_ids
  from iam.membership_store_scopes scope
  join iam.stores store on store.id = scope.store_id
    and store.tenant_id = scope.tenant_id
  where scope.tenant_id = v_tenant_id
    and scope.user_id = v_user_id
    and scope.is_default
    and store.status = 'active';

  if coalesce(cardinality(v_store_ids), 0) = 0
    and v_role in ('owner', 'store_owner') then
    perform iam.bootstrap_owner('My Store');

    select array_agg(scope.store_id)
    into v_store_ids
    from iam.membership_store_scopes scope
    join iam.stores store on store.id = scope.store_id
      and store.tenant_id = scope.tenant_id
    where scope.tenant_id = v_tenant_id
      and scope.user_id = v_user_id
      and scope.is_default
      and store.status = 'active';
  end if;

  if coalesce(cardinality(v_store_ids), 0) <> 1 then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Exactly one active default store is required.","details":{}}';
  end if;

  v_active_store_id := v_store_ids[1];

  select store.code, store.display_name
  into v_active_store_code, v_active_store_display_name
  from iam.stores store
  where store.tenant_id = v_tenant_id
    and store.id = v_active_store_id
    and store.status = 'active';

  if v_active_store_code is null or v_active_store_display_name is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Active store identity is required.","details":{}}';
  end if;

  if v_role in ('owner', 'store_owner') then
    v_permissions := array[]::text[];
  else
    select coalesce(array_agg(rp.permission order by rp.permission), array[]::text[])
    into v_permissions
    from iam.role_permissions rp
    where rp.role = v_role;
  end if;

  return jsonb_build_object(
    'user_id', v_user_id,
    'tenant_id', v_tenant_id,
    'active_store_id', v_active_store_id,
    'active_store_code', v_active_store_code,
    'active_store_display_name', v_active_store_display_name,
    'role', v_role,
    'permissions', to_jsonb(v_permissions)
  );
end;
$$;

create or replace function iam.bootstrap_owner(p_tenant_name text default 'My Store')
returns uuid
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_ids uuid[];
  v_tenant_id uuid;
  v_role text;
  v_store_id uuid;
begin
  if v_user_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"NOT_AUTHENTICATED","message":"Not authenticated.","details":{}}';
  end if;

  select array_agg(m.tenant_id)
  into v_tenant_ids
  from iam.memberships m
  where m.user_id = v_user_id;

  if coalesce(cardinality(v_tenant_ids), 0) = 0 then
    insert into iam.tenants (name)
    values (coalesce(nullif(trim(p_tenant_name), ''), 'My Store'))
    returning id into v_tenant_id;

    insert into iam.memberships (tenant_id, user_id, role)
    values (v_tenant_id, v_user_id, 'store_owner');
  elsif cardinality(v_tenant_ids) = 1 then
    v_tenant_id := v_tenant_ids[1];
  else
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Exactly one tenant context is required.","details":{}}';
  end if;

  select m.role
  into v_role
  from iam.memberships m
  where m.tenant_id = v_tenant_id
    and m.user_id = v_user_id;

  if v_role not in ('owner', 'store_owner') then
    raise exception using errcode = 'P0001',
      message = '{"code":"PERMISSION_DENIED","message":"Only tenant owners can bootstrap stores.","details":{}}';
  end if;

  insert into iam.stores (tenant_id, code, display_name, status)
  values (v_tenant_id, 'default', 'Default Store', 'active')
  on conflict (tenant_id, code) do update
  set display_name = excluded.display_name, status = 'active'
  returning id into v_store_id;

  insert into iam.membership_store_scopes (
    tenant_id,
    user_id,
    store_id,
    is_default
  ) values (
    v_tenant_id,
    v_user_id,
    v_store_id,
    true
  )
  on conflict (tenant_id, user_id, store_id) do update
  set is_default = true;

  return v_tenant_id;
end;
$$;

revoke all on iam.stores from public, anon;
revoke all on iam.membership_store_scopes from public, anon;
grant select on iam.stores, iam.membership_store_scopes to authenticated;

revoke all on function iam.get_session_context(uuid) from public, anon;
revoke all on function iam.bootstrap_owner(text) from public, anon;
grant execute on function iam.get_session_context(uuid) to authenticated;
grant execute on function iam.bootstrap_owner(text) to authenticated;
